USE dbWMS;
IF OBJECT_ID('dbo.RMSubTransfers','U') IS NULL CREATE TABLE dbo.RMSubTransfers(TransferId int IDENTITY PRIMARY KEY,RequestId uniqueidentifier NOT NULL UNIQUE,TransferNo nvarchar(40) NOT NULL UNIQUE,ProductId int NOT NULL,SourceWhId int NOT NULL,SourceLocation nvarchar(50) NOT NULL,DestinationWhId int NOT NULL,DestinationLocation nvarchar(50) NOT NULL,PackCount int NOT NULL CHECK(PackCount>0),QuantityBase decimal(18,2) NOT NULL CHECK(QuantityBase>0),PackUnit nvarchar(30) NOT NULL,ContentUnit nvarchar(30) NOT NULL,ContentPerPack decimal(18,6) NOT NULL,BasePerContentUnit decimal(18,6) NOT NULL,BaseUnit nvarchar(30) NOT NULL,Status varchar(12) NOT NULL DEFAULT 'SENT' CHECK(Status IN('SENT','RECEIVED','CANCELLED')),ReferenceNo nvarchar(60) NOT NULL,Note nvarchar(255) NULL,RequestJson nvarchar(max) NOT NULL,CreatedBy nvarchar(100) NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSDATETIME(),ReceivedBy nvarchar(100) NULL,ReceivedAt datetime2 NULL,CancelledBy nvarchar(100) NULL,CancelledAt datetime2 NULL);
IF OBJECT_ID('dbo.RMSubTransferContainers','U') IS NULL CREATE TABLE dbo.RMSubTransferContainers(TransferId int NOT NULL REFERENCES dbo.RMSubTransfers(TransferId),ContainerId int NOT NULL REFERENCES dbo.RMContainers(ContainerId),QuantityBase decimal(18,2) NOT NULL CHECK(QuantityBase>0),LotNo nvarchar(60) NOT NULL,ExpiryDate date NULL,PRIMARY KEY(TransferId,ContainerId));
IF OBJECT_ID('dbo.RMSubTransferAudit','U') IS NULL CREATE TABLE dbo.RMSubTransferAudit(AuditId int IDENTITY PRIMARY KEY,TransferId int NOT NULL REFERENCES dbo.RMSubTransfers(TransferId),Action varchar(20) NOT NULL,Actor nvarchar(100) NOT NULL,Details nvarchar(max) NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSDATETIME());
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_RMSubTransfers_Pending' AND object_id=OBJECT_ID('dbo.RMSubTransfers')) CREATE INDEX IX_RMSubTransfers_Pending ON dbo.RMSubTransfers(Status,ProductId,SourceWhId,DestinationWhId);
